result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/astar.py", "content": """"A* on an ASCII grid with Manhattan heuristic (stdlib only)."""
import heapq

MAP = """\
S--#-
-#-#-
-#---
-#-#-
---#G"""

OPEN = {"-", "S", "G"}
MOVES = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def parse(text):
    grid = [list(row) for row in text.splitlines()]
    start = goal = None
    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch == "S":
                start = (r, c)
            elif ch == "G":
                goal = (r, c)
    assert start and goal
    return grid, start, goal


def h(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])


def astar(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    open_cells = {(r, c) for r in range(rows) for c in range(cols)
                  if grid[r][c] in OPEN}
    counter = 0  # tie-breaker
    g = {start: 0}
    came = {}
    frontier = [(h(start, goal), counter, start)]
    expanded = 0

    while frontier:
        f, _, cur = heapq.heappop(frontier)
        if cur == goal:
            path = [cur]
            while cur in came:
                cur = came[cur]
                path.append(cur)
            return path[::-1], expanded
        if f - h(cur, goal) > g.get(cur, float("inf")):
            continue  # stale entry
        expanded += 1
        dr, dc = cur
        for ndr, ndc in MOVES:
            nxt = (dr + ndr, dc + ndc)
            if nxt not in open_cells:
                continue
            ng = g[cur] + 1
            if ng < g.get(nxt, float("inf")):
                g[nxt] = ng
                came[nxt] = cur
                counter += 1
                heapq.heappush(frontier, (ng + h(nxt, goal), counter, nxt))
    raise ValueError("no path")


def solve():
    grid, start, goal = parse(MAP)
    return grid, start, goal, *astar(grid, start, goal)


def render(grid, path):
    marked = [row[:] for row in grid]
    for r, c in path:
        if marked[r][c] not in ("S", "G"):
            marked[r][c] = "*"
    return "\n".join("".join(row) for row in marked)


if __name__ == "__main__":
    _, _, _, path, _ = solve()
    print(render(parse(MAP)[0], path))
