from astar import MAP, OPEN, MOVES, parse, solve, render


@pytest.fixture(scope="module")
def result():
    return solve()


def test_path_length_is_8(result):
    grid, start, goal, path, _ = result
    assert len(path) - 1 == 8
    assert abs(start[0] - goal[0]) + abs(start[1] - goal[1]) == 8  # optimal


def test_path_endpoints(result):
    _, start, goal, path, _ = result
    assert path[0] == start == (0, 0)
    assert path[-1] == goal == (4, 4)


def test_every_step_is_adjacent_open_cell(result):
    grid, _, _, path, _ = result
    for a, b in zip(path, path[1:]):
        assert (b[0] - a[0], b[1] - a[1]) in MOVES  # 4-connected
        assert grid[b[0]][b[1]] in OPEN  # never a wall / off-map


def test_expanded_nodes_bounded_by_open_cells(result):
    grid, _, _, path, expanded = result
    open_count = sum(ch in OPEN for row in grid for ch in row)
    assert 0 < expanded <= open_count


def test_render_shows_overlaid_path(result):
    grid, _, _, path, _ = result
    out = render(grid, path)
    print("\n" + out)
    assert out.count("*") == 6  # 9 cells minus S and G
